#include <algorithm>
#include <functional>
#include <iostream>
#include <vector>
int main() {
  std::vector<int> values{90, 60, 30};
  auto it = std::lower_bound(
      values.begin(), values.end(), 75, std::greater<>{});
  if (it == values.end()) std::cout << "end";
  else std::cout << *it;
}
